-- GENERATED by `wfj generate` from data/gossip/gossip-1c.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["1c01b077463ceae3"] = { "Ladri! Furfanti! Canaglie! Venite ad affrontare i miei pilastri giganteschi!", "." },
  ["1c1e77ca8c8429a0"] = { "Se solo la giornata avesse qualche ora in più...", "." },
  ["1c2605f960cd96a6"] = { "Morirai qui. <La tua mente si riempie di visioni di caos e distruzione.>", "." },
  ["1c27d7ef00472bd6"] = { "Ach! Passami una birra gelata, Belm!", "." },
  ["1c29f7441daf01dd"] = { "Uau! Guarda che centro!", "." },
  ["1c2c52d197c7866e"] = { "%s prende la mira con più attenzione...", "." },
  ["1c2e4d7dc812511f"] = { "Sei <giunto/giunta> proprio mentre stavano per gettarmi in pasto ai demoni di sotto, e per questo ti ringrazio. Forse io... anzi, noi dello Stormo dei Draghi Blu possiamo aiutarti ancora?\n\nHai fatto tanta strada, {race}, e rischiato molto. Vuoi spingerti ancora un po' oltre per combattere Nefarian e la sua legione dei ⟦Blackrock=Roccianera⟧?", "." },
  ["1c309351c8316428"] = { "%s si volta verso il bersaglio di carta...", "." },
  ["1c36878137454228"] = { "I Windshaper non dimenticano, e il sangue si paga sempre con il sangue. Mi compiace che tu sia riuscit<o/a> a consegnare a quel traditore quest'ultimo, doloroso promemoria del nostro credo.\n\nTuttavia, questo cuore non sarà l'unica cosa ad alimentare le fiamme oggi. C'è un altro compito da svolgere.", "." },
  ["1c3947a81b757649"] = { "Ora il capo sei tu, amico!", "." },
  ["1c454c9206a3e1c2"] = { "Rappresento la forza che ti sostiene come giovane <druido/druida>. Sono la forza del corpo e la forza del cuore. L'hai già conosciuta durante il tuo addestramento, e vi attingi quando assumi l'aspetto dell'orso.\n\nContinua a mantenere l'equilibrio in ogni cosa, giovane, e mantieni il tuo sguardo limpido e sincero. Quando avrai bisogno di me... io ci sarò.", "." },
  ["1c52c0582bb6e7ec"] = { "Non sarebbe glorioso se in qualche modo riuscissi a sconfiggermi, ma non prima che io abbia distrutto l'unica speranza che Kalimdor possa avere? Fremo d'attesa. Presto... Presto sarà polvere.", "." },
  ["1c55e01396904489"] = { "Un pesce? Hai dato a un pesce un pezzo di quella che potrebbe essere la chiave per salvare tutta la vita su Kalimdor?", "." },
  ["1c63c039bbc670a7"] = { "Seguire le tracce, eh? Allora devi andare a trovare Denmul Farmountain. Ti insegnerà i trucchi del mestiere come nessun altro.\n\nVa' a sud dalle porte di ⟦Ironforge=Forgiardente⟧ fino al Military District per trovarlo.", "." },
  ["1c6893b1cd4e3e3c"] = { "TEST - morte prima dell'attacco {name}", "." },
  ["1c6a046138fa945d"] = { "Salute, <figliolo/figliola>. Sono ⟦Illaya Amberwind=Illaya Vento d'Ambra⟧, l'anziana Windshaper qui a Zephras Isle. È sempre bello incontrare volti giovani e nuovi che scendono dal boschetto.\n\nNon lasciare che questa vecchia sciamana ti trattenga, avrai senz'altro molte avventure da affrontare. Passa pure più tardi, se ti va.", "." },
  ["1c74ea6e774c4d8d"] = { "Se cerchi la migliore maestria artigiana di questo o di qualunque altro continente del mondo, sei nel posto giusto!\n\nGrimand Elmore, al tuo servizio!", "." },
  ["1c8604f581269215"] = { "Vedi il vago profilo di una figura umanoide dentro il baccello; ora sai che questo è davvero il posto in cui devi trovarti. Anche se pensi che prima o poi riuscirai ad aprirlo, il baccello resta ben chiuso anche ai tuoi tentativi più energici.", "." },
  ["1c8e5bb3f1f932d6"] = { "Ah, molto gentile, Corbett. Li mettiamo subito sulle rastrelliere.", "." },
  ["1c905e3212889a17"] = { "Le nostre antiche terre nel nord-est dei Regni Orientali. Chiamate così in onore di Lordain in persona, un tempo furono un regno fiero e potente. La sua storia è ricca e offre molte lezioni a nobili e re presuntuosi. Uno dei suoi momenti decisivi fu il contributo alla fondazione dell'⟦Alliance=Alleanza⟧ che conosciamo oggi.\n\nPurtroppo la sua storia è anche oscura, e i suoi attuali abitanti ne profanano le terre giorno dopo giorno. Nelle rovine che ora sorgono sopra ⟦Undercity=Sepulcra⟧ c'è ancora molto di importante, ma è follia tentare quel viaggio e aspettarsi di tornare ancora tra i vivi.", "." },
  ["1ca1e3e6a61e457c"] = { "Parla con me, {name}: se lo desideri, il ⟦Cenarion Circle=Circolo Cenariano⟧ accetterà con entusiasmo la tua generosa offerta d'aiuto. La minaccia rappresentata dalla Vil Vite di Eldre'Thalas è davvero grave.", "." },
  ["1ca593264a65e7e2"] = { "Il ⟦Icewing Bunker=Fortilizio di Algidala⟧ è sotto attacco! Se nessuno interviene, l'⟦Horde=Orda⟧ lo distruggerà!", "." },
  ["1ca766ec6586f8cc"] = { "Aku'mai è morto! Finalmente posso lasciare questo posto maledetto.", "." },
  ["1cc005467bba384a"] = { "{name} ha catturato la Bandiera dell'⟦Alliance=Alleanza⟧!", "." },
  ["1cc47f2d9711f5dd"] = { "⟦Yonn Deepcut=Yonn Taglio Fondo⟧ si trova nella grande tenda nell'angolo nord-occidentale del ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "." },
  ["1cc5264429fd13ab"] = { "Grark Lorkrub, sei stato accusato e giudicato colpevole di tradimento contro l'⟦Horde=Orda⟧. Come ti dichiari non ha importanza. Gran boia Nuzrak, fatti avanti.", "." },
  ["1cc81bbfefa2146f"] = { "Tu controlla davanti!", "." },
  ["1cd1ae3d8c60a0b7"] = { "Non sembra... giusto. Guarda quanto è alieno questo deserto! Passare di qui potrebbe essere un terribile errore.", "." },
  ["1cd20643e0e705a4"] = { "L'anziana Filastelle si trova nel villaggio costiero di Auberdine, a ⟦Darkshore=Rivafosca⟧.", "." },
  ["1cdb8059af775f2e"] = { "Forza, fannulloni, è ora di alzarsi e mettersi al lavoro. Quel ponte non si costruisce da solo.", "." },
  ["1ce38290b3b35b5d"] = { "Sarebbe magnifico! Grazie, Meridith.", "." },
  ["1cebdb1b635fbf8b"] = { "%s armeggia con la serratura arrugginita della porta del cortile.", "." },
  ["1cf04265226bd07a"] = { "Sembra che ti serva un po' di lavoro, <giovanotto/signorina>. Dovresti salire sul tram e andare a trovare mio fratello, Monty, al deposito del ⟦Deeprun Tram=Tram degli Abissi⟧ di ⟦Ironforge=Forgiardente⟧. Di certo avrà qualcosa da farti fare.", "." },
  ["1cf342f957789b45"] = { "Salute, {name}. Vuoi entrare in battaglia alle Isole dei ⟦Darkspear=Lanciascura⟧?", "." },
  ["1cfac513d0422938"] = { "Credo che voi bambini siate il nostro futuro...", "." },
  ["1cff4ecf21c0f9db"] = { "Parlami della pelle.", "." },
})
